import{_ as t,o as s,c as a,a2 as n}from"./chunks/framework.CdvW4CUT.js";const h=JSON.parse('{"title":"第 21 章　选型决策与迁移路径","description":"","frontmatter":{},"headers":[],"relativePath":"06-case-study/21-选型决策与迁移路径.md","filePath":"06-case-study/21-选型决策与迁移路径.md","lastUpdated":1793361704000}'),o={name:"06-case-study/21-选型决策与迁移路径.md"};function d(p,e,r,c,i,l){return s(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="第-21-章-选型决策与迁移路径" tabindex="-1">第 21 章　选型决策与迁移路径 <a class="header-anchor" href="#第-21-章-选型决策与迁移路径" aria-label="Permalink to &quot;第 21 章　选型决策与迁移路径&quot;">​</a></h1><p>2026 年 6 月，一家做医疗器械售后的团队选定了某托管记忆平台，理由充分：上线快、免运维、按量付费。十个月后，他们接到客户的合规审计要求——所有涉及患者设备使用记录的派生结论必须能证明已彻底删除，且要给出删除时刻的证据。平台提供操作日志，提供不了完整性证明；把日志导出给审计方之后，对方问了一句「你怎么证明日志本身没被改过」，会议室安静了半分钟。</p><p>这不是选错了产品，而是选型时没把一个问题提前问出来。那家平台在其定位上做得很好，它只是不承诺「可验证的删除证据」这件事。团队在选型阶段比较的是延迟、价格与召回效果，没有比较「三年后会不会被要求举证」。选型的困难不在信息，而在顺序：先比能力再问约束，几乎必然返工；先问约束再比能力，能砍掉一大半候选。本章按这个顺序展开——21.1 是五个必须先答的问题，21.2 把它们压成一棵决策树，21.3 说明为什么某些选择比其他选择更难撤回，21.4 到 21.6 是三条迁移路径（按改动幅度从小到大排列），21.7 给一份验收清单：迁移是否成功，不由「能跑起来」判定。</p><p>术语约定：本节所说的「迁移」指把记忆层从 A 换到 B，且保留既有数据与调用方代码；不包含模型、向量库或编排框架的替换。</p><h2 id="_21-1-选型前必须回答的五个问题" tabindex="-1">21.1 选型前必须回答的五个问题 <a class="header-anchor" href="#_21-1-选型前必须回答的五个问题" aria-label="Permalink to &quot;21.1 选型前必须回答的五个问题&quot;">​</a></h2><p>这五个问题的共同点是：答错的代价不在上线时显现，而在两年后的一次审计、一次扩容或一次团队交接时显现。</p><table tabindex="0"><thead><tr><th>问题</th><th>若答「是」</th><th>若答「否」</th></tr></thead><tbody><tr><td>数据主权是硬约束吗</td><td>只剩自托管路线</td><td>托管方案可进入候选</td></tr><tr><td>团队有运维能力吗</td><td>自托管可行</td><td>托管或零依赖方案</td></tr><tr><td>记忆需跨 Agent 共享吗</td><td>需上层权限模型</td><td>物理隔离即可满足</td></tr><tr><td>需要可验证的删除证据吗</td><td>必须具备哈希链</td><td>操作日志够用</td></tr><tr><td>中文占比高吗</td><td>必须实测分词策略</td><td>默认分词通常够用</td></tr></tbody></table><p>表 21-1　五个前置问题如何收窄候选集</p><p><strong>第一问：数据主权是不是硬约束。</strong> 判断标准不是「我们重视数据安全」，而是「数据能否离开我方控制的网络」。医疗、金融、政务与部分制造业客户会把这条写进合同，一旦写进去，托管方案整条路线出局，比较维度随之从「功能多少」变成「自托管能做多全」。这一问答错的代价最高，因为它不可协商。</p><p><strong>第二问：团队有没有运维能力。</strong> 自托管的真实成本不是装一个服务，而是长期维护图数据库、备份、升级与故障恢复。有 DBA 与 SRE 的团队可以承担；三个人的产品团队承担不了。这里要抵抗一种常见的乐观：把 PoC 阶段「跑起来了」当成运维能力证明。</p><p><strong>第三问：记忆是否需要跨 Agent 共享。</strong> 物理隔离的实现方式（每个作用域组合一个独立 SQLite 文件）天然支持「不共享」，但一旦要求两个 Agent 读同一份记忆，就需要在上层自建权限模型。这个问题的答案会决定第 23 章那个未解问题是否会砸到自己头上。</p><p><strong>第四问：是否需要可验证的删除证据。</strong> 区分两种需求：「删除生效」与「能证明删除发生过且不可否认」。前者操作日志够用，后者需要哈希链审计账本。多数团队以为自己只需要前者，直到第一次被审计问到。</p><p><strong>第五问：中文占比高吗。</strong> 如果记忆内容以中文为主，且查询里含型号、人名、专有名词，纯嵌入召回会失准，必须实测分词与关键词通道的效果。这一问的验证成本很低，跳过它没有理由。</p><h2 id="_21-2-决策树" tabindex="-1">21.2 决策树 <a class="header-anchor" href="#_21-2-决策树" aria-label="Permalink to &quot;21.2 决策树&quot;">​</a></h2><p>把五问压成树，可以在半小时内把候选从六个砍到两个。这棵树不追求完备，它追求的是「先排除明显不合适的」。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Q0 数据主权是硬约束？</span></span>
<span class="line"><span>├─ 是 → 只能自托管</span></span>
<span class="line"><span>│   ├─ 有图数据库运维能力？</span></span>
<span class="line"><span>│   │   ├─ 是 → Zep 路线（Graphiti 自建）或 Mnemosyne 自托管</span></span>
<span class="line"><span>│   │   └─ 否 → Mnemosyne 自托管（单文件 SQLite，零依赖启动）</span></span>
<span class="line"><span>│   ├─ 需要零依赖快速验证（离线 / 无 key / 无模型）？</span></span>
<span class="line"><span>│   │   └─ 是 → Mnemosyne（内置 rules 提取器与 128 维嵌入器）</span></span>
<span class="line"><span>│   └─ 已在 LangGraph 生态且只需 SDK？</span></span>
<span class="line"><span>│       └─ 是 → LangMem + 自备持久化 store</span></span>
<span class="line"><span>├─ 否 → 可托管，继续问</span></span>
<span class="line"><span>│   ├─ 目标是对话个性化快速上线？</span></span>
<span class="line"><span>│   │   └─ 是 → Mem0（Free 起步，图记忆需 Custom）</span></span>
<span class="line"><span>│   ├─ 需要 Agent 自主管理记忆与运行时？</span></span>
<span class="line"><span>│   │   └─ 是 → Letta（npm 安装 + Letta Cloud）</span></span>
<span class="line"><span>│   └─ 已在 Workers 生态且状态贴着执行环境？</span></span>
<span class="line"><span>│       └─ 是 → Cloudflare Agents（Durable Objects）</span></span>
<span class="line"><span>└─ 混合 → 托管做前台个性化，自托管做合规存档</span></span>
<span class="line"><span>    └─ 注意：两套记忆之间的同步与一致性由你负责</span></span></code></pre></div><p>这段决策树的用法是：从 Q0 开始一路走到底，得到的是一个起点而不是终点。走到「混合」分支时要格外小心，因为混合形态把一致性问题的所有权从供应商转移给了自己。</p><h2 id="_21-3-决策的不可逆性" tabindex="-1">21.3 决策的不可逆性 <a class="header-anchor" href="#_21-3-决策的不可逆性" aria-label="Permalink to &quot;21.3 决策的不可逆性&quot;">​</a></h2><p>选型讨论常把六个方案摆成一张平表，暗示它们可以随时互换。实际不是：不同方向的迁移成本差异极大，而这个差异有结构。</p><p><strong>从自托管切到托管，成本主要在数据搬迁与接口适配。</strong> 数据在你手里，导出是你能单方面决定的事；接口差异有明确的映射表可查。这类迁移通常以周计。<strong>从托管切回自托管，成本还包括一段时间的双写与对账。</strong> 你不能停掉线上服务去搬数据，只能双写、比对、切换、观察。更麻烦的是那些「平台替你做了但你没意识到」的部分：巩固、去重、衰减排序。切走之后这些工序会突然消失，而它们消失的症状是召回质量缓慢下降，不是报错。</p><p><strong>因此有一条默认规则：存在任何数据主权不确定性时，起点选自托管是更安全的默认。</strong> 代价是前期投入更高、上线更慢；收益是保留了向任一方向调整的自由。这条规则的失效条件是「上线窗口只有两周」——那时先上线再迁移是唯一可行路径，但必须在架构上预留导出与双写的能力，否则第二次迁移会被数据卡住。</p><h2 id="_21-4-迁移路径一-从-mem0-到-mnemosyne" tabindex="-1">21.4 迁移路径一：从 Mem0 到 Mnemosyne <a class="header-anchor" href="#_21-4-迁移路径一-从-mem0-到-mnemosyne" aria-label="Permalink to &quot;21.4 迁移路径一：从 Mem0 到 Mnemosyne&quot;">​</a></h2><p>这是三条路径里改动最小的一条，原因是工具名与调用形状都对齐了。</p><p><strong>工具面。</strong> Mnemosyne 实现了 11 个常规 agent-memory 工具名：<code>add_memory</code>、<code>search_memories</code>、<code>get_memories</code>、<code>get_memory</code>、<code>update_memory</code>、<code>delete_memory</code>、<code>delete_all_memories</code>、<code>delete_entities</code>、<code>list_entities</code>、<code>list_events</code>、<code>get_event_status</code>。把现有 MCP 客户端指向新端点，提示词不必改。</p><p><strong>代码面。</strong> <code>Memory</code>、<code>AsyncMemory</code> 与 <code>MemoryClient</code> 接受常规的 agent-memory 调用形状，因此已经按那个形状写好的代码，改 import 即可：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> mnemosyne </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Memory          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 原来是从另一处 importm = Memory()m.add([{&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: &quot;我搬到了柏林&quot;}], user_id=&quot;alice&quot;)hits = m.search(&quot;用户住在哪&quot;, filters={&quot;user_id&quot;: &quot;alice&quot;})</span></span></code></pre></div><p>这段代码验证的是调用形状的兼容性：<code>add</code> 接受消息列表加 <code>user_id</code>，<code>search</code> 接受过滤条件。注意返回值结构仍需核对——形状兼容不等于字段完全一致。</p><p><strong>一个已经失效的迁移理由。</strong> 早期文档常说「Mem0 的两阶段 ADD/UPDATE/DELETE 流水线导致迁移困难」。这条理由在 2026 年已不成立：Mem0 现在也是单遍 ADD-only 提取，一次 LLM 调用，只增不覆盖不删除。既然两边范式相同，迁移的技术障碍就不在写入侧。</p><p><strong>真正的差异有三处。</strong> 其一，<code>update_memory</code> 的语义：Mnemosyne 的 <code>update_memory</code> 是显式覆盖正文与元数据，而 ADD-only 系统表达「现在是什么」靠检索时的排序而非覆盖；迁移时要检查调用方是否隐含依赖「显式覆盖即当前状态」这个假设，如果有，那个假设在两边都不可靠。其二，图记忆的归属：Mem0 的图记忆（实体链接）是 Platform 能力，开源版官方标注该能力已移除，开源侧不存在可查询的图；Mnemosyne 的图记忆内建在同一个 SQLite 文件里，不需要外部图数据库，若原方案依赖 Platform 的图能力，迁移到自托管后这部分要重新设计。其三，审计能力：Mem0 的审计日志属 Custom 层，是操作日志；Mnemosyne 的哈希链账本能指出具体哪一条被改——这是能力增强，代价是写入路径串行化。</p><h2 id="_21-5-迁移路径二-从-zep-到-mnemosyne" tabindex="-1">21.5 迁移路径二：从 Zep 到 Mnemosyne <a class="header-anchor" href="#_21-5-迁移路径二-从-zep-到-mnemosyne" aria-label="Permalink to &quot;21.5 迁移路径二：从 Zep 到 Mnemosyne&quot;">​</a></h2><p>改动中等，难点不在工具名，而在返回值的形状。</p><p><strong>工具面。</strong> Zep 的 Context MCP Server 暴露 12 个工具，分两组。用户自有图一组 6 个：<code>search_graph</code>、<code>get_user_summary</code>、<code>get_subgraph</code>、<code>get_node_neighbors</code>、<code>list_episodes</code>、<code>add_memory</code>。共享 Context Graph 一组 6 个：<code>list_graphs</code>、<code>search_graph_in</code>、<code>get_subgraph_in</code>、<code>get_node_neighbors_in</code>、<code>list_episodes_in</code>、<code>add_memory_to_graph</code>，另提供 <code>zep://graphs/directory</code> 资源。Mnemosyne 侧没有同名的图遍历工具，对应能力是 <code>graph_query</code>、<code>temporal_query</code> 与 <code>expand_memory</code> 返回的图邻居。</p><p><strong>形状差异是关键。</strong> <code>search_graph</code> 在 <code>scope=auto</code> 下返回的是<strong>组装好的上下文块</strong>，可以直接拼进提示词；Mnemosyne 的 <code>recall</code> 与 <code>expand_memory</code> 返回<strong>结构化记忆条目</strong>，带分数、信封、证据链，需要调用方自己组装。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Zep:       search_graph(scope=auto) → 可直接注入的文本块Mnemosyne: recall(...) → 条目列表 → 自行拼接 → 注入文本</span></span></code></pre></div><p>这层组装不是纯粹的成本，它同时给了你控制权：可以按分数阈值过滤、按时间排序、按层分配预算。但如果下游代码里到处是「拿到字符串就拼」的写法，这层组装会散落在十几处，迁移工期主要消耗在这里。</p><p><strong>语义粒度的替代方案。</strong> Zep 用 <code>scope</code> 让调用方选粒度（<code>auto</code> / <code>observations</code> / <code>thread_summaries</code> / <code>episodes</code> / <code>nodes</code> / <code>edges</code>）。Mnemosyne 没有同名参数，对应的做法是 <code>recall_catalog</code> 先看目录、<code>expand_memory</code> 再展开 1–2 条。两者解决同一个问题，代价不同：前者要求调用方懂语义层级，后者多一次往返。迁移时要把原来一处调用里的粒度决策，拆成编排层的两次调用。</p><h2 id="_21-6-迁移路径三-从-letta-到-mnemosyne" tabindex="-1">21.6 迁移路径三：从 Letta 到 Mnemosyne <a class="header-anchor" href="#_21-6-迁移路径三-从-letta-到-mnemosyne" aria-label="Permalink to &quot;21.6 迁移路径三：从 Letta 到 Mnemosyne&quot;">​</a></h2><p>改动最大的一条，因为两者的记忆在架构里的位置不同。<strong>位置差异。</strong> Letta 的记忆是 Agent runtime 的一部分：概念面包含 MemFS（git 版本化的 Agent 记忆文件系统，默认没有向量索引）与共享记忆。Agent 通过编辑文件来改自己的记忆，记忆的读写是 Agent 行为的一部分。Mnemosyne 是外部服务，记忆通过工具调用读写，Agent 本身不持有记忆状态。</p><p><strong>因此改动落在控制流上，不在接口上。</strong> 原来 Agent 的循环是「读记忆文件 → 思考 → 编辑记忆文件」；迁移后是「思考 → 调用 <code>recall</code> 或 <code>recall_catalog</code> → 拿到条目 → 继续」。这不是替换一个函数，而是改写 Agent 的行动空间：从文件编辑这种开放式动作，变成有限个工具调用。</p><p><strong>代价有两面。</strong> 一面是能力收窄：文件编辑能表达任意结构，工具调用只能表达工具定义过的结构。另一面是可治理性提升：每次读写都留下事件记录，可审计、可回放、可限制。团队要判断自己更需要哪一面——需要 Agent 自由组织记忆结构的场景，这次迁移是降级；需要记忆行为可被审计与约束的场景，这次迁移是升级。<strong>一个容易低估的工程量：迁移历史记忆。</strong> MemFS 里的记忆是文件，没有统一的 schema，转成结构化条目需要写解析与归类规则。这部分工作量通常超过接口改造本身，且无法自动化到底。</p><h2 id="_21-7-迁移的验收清单" tabindex="-1">21.7 迁移的验收清单 <a class="header-anchor" href="#_21-7-迁移的验收清单" aria-label="Permalink to &quot;21.7 迁移的验收清单&quot;">​</a></h2><p>迁移是否成功，不由「服务起来了、工具能调」判定。下面五项按顺序执行，任一项不通过就不进入下一项。</p><table tabindex="0"><thead><tr><th>项</th><th>做法</th><th>不通过的信号</th></tr></thead><tbody><tr><td>工具名兼容</td><td>用原提示词跑一遍回归</td><td>模型反复调错工具名</td></tr><tr><td>召回质量 A/B</td><td>同一批查询双跑，比对 top-5</td><td>命中率下降且集中在专名</td></tr><tr><td>删除语义回归</td><td>删一条后查派生结论是否失效</td><td>派生摘要仍可召回</td></tr><tr><td>审计链可用性</td><td><code>verify_integrity()</code> 应返回 valid</td><td>返回 first_broken_at</td></tr><tr><td>回滚预案</td><td>保留旧库只读副本与切回开关</td><td>只能靠重新导入</td></tr></tbody></table><p>表 21-2　迁移验收五项与各自的失败信号</p><p>第一项最容易被跳过，因为「工具名一样」看起来是显然的。实际上模型对工具描述文本敏感，描述改写会改变调用习惯，必须用原提示词回归而不是新写测试。</p><p>第二项的关键是<strong>分层看结果</strong>，不只看总分。总分持平但专名类查询下降，说明关键词通道没接上；总分下降但时序类查询上升，说明时间信号更强了但语义通道弱了。只看总分会把这两种情况混成一个「差不多」。</p><p>第三项针对 ADD-only 的固有弱点：源记录删了，派生结论还在。<code>memory_cascade_delete</code> 的 <code>dry_run=true</code> 能先列出依赖项，验收时应该先跑 dry_run 看清单是否符合预期，再执行。第五项最容易被当成形式，回滚预案的可执行标准是：能在不重新导入的前提下切回旧库，并且旧库在切换期间保持只读但可查。</p><h2 id="_21-8-本章小结" tabindex="-1">21.8 本章小结 <a class="header-anchor" href="#_21-8-本章小结" aria-label="Permalink to &quot;21.8 本章小结&quot;">​</a></h2><p>本章确立三条判断。</p><p><strong>第一，选型的顺序比选型的方法更重要。</strong> 先答五个前置问题再比能力，能把候选从六个砍到两个；反过来先比能力，几乎必然在合规或运维环节返工。这套顺序成立的条件是五个问题都能被明确回答；它失效的条件是组织内部对「数据主权是否硬约束」本身没有共识——那时先解决共识，再谈选型。</p><p><strong>第二，迁移成本的方向不对称，因此默认起点应当偏向可撤回的一侧。</strong> 从自托管切到托管以周计，反向以月计，且要处理平台替你做过而你没意识到的工序。这条判断的代价是前期投入更高；它的失效条件是上线窗口极短，那时必须在架构上预留导出与双写能力作为补偿。</p><p><strong>第三，三条迁移路径的难度差异来自「记忆在架构里的位置」，不来自接口数量。</strong> Mem0 到 Mnemosyne 只是改 import 与核对字段；Zep 到 Mnemosyne 要补一层组装；Letta 到 Mnemosyne 要改写 Agent 的行动空间。判断自己的迁移属于哪一类，看一个问题就够了：原系统里，记忆是 Agent 的行为对象，还是 Agent 调用的服务？</p><p>还有一个问题留在这里：三条路径的验收清单都假设「你知道迁移前的召回质量是多少」。如果迁移前没有基线，A/B 就无从做起。这个空缺会在第 22 章以验收方法的形式再次出现，并在第 23 章成为「基准与真实使用之间的鸿沟」的一部分。</p><hr>`,54)])])}const g=t(o,[["render",d]]);export{h as __pageData,g as default};
